#include <iostream>
#include <vector>

// The solution file defines this struct identically; the layout must match.
struct ListNode
{
    int val;
    ListNode* next;
};

const ListNode* CycleStart(const ListNode* head);

int main()
{
    int n, pos;
    while (std::cin >> n >> pos)
    {
        std::vector<ListNode*> nodes(n);
        for (int i = 0; i < n; i++)
        {
            int v;
            std::cin >> v;
            nodes[i] = new ListNode{v, nullptr};
        }
        for (int i = 0; i + 1 < n; i++)
        {
            nodes[i]->next = nodes[i + 1];
        }
        if (n > 0 && pos >= 0)
        {
            nodes[n - 1]->next = nodes[pos];
        }

        const ListNode* r = CycleStart(n > 0 ? nodes[0] : nullptr);
        int found = -1;
        for (int i = 0; i < n; i++)
        {
            if (nodes[i] == r) { found = i; }
        }
        if (r == nullptr)      { std::cout << "none\n"; }
        else if (found < 0)    { std::cout << "foreign node\n"; }
        else                   { std::cout << "cycle at index " << found << "\n"; }

        for (ListNode* p : nodes) { delete p; }
    }
    return 0;
}

