"""Random lists of 0 to 14 nodes; about two thirds loop back to a random
earlier node (including the node itself and the head)."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 14)
    pos = rng.randrange(n) if n and rng.random() < 0.67 else -1
    values = [rng.randint(0, 9) for _ in range(n)]
    return {"name": "%d nodes, tail links to %d #%d" % (n, pos, index),
            "stdin": "%d %d\n%s\n" % (n, pos, " ".join(map(str, values)))}
